from pathlib import Path
import json,html,ast
out=Path('docs/frappe-accounting')
old=Path('docs/akaunting/build-guide.py').read_text(encoding='utf-8')
helpers=old[old.index('def table('):old.index('feature=tree(')]
sources=[('ERPNext accounting introduction','https://docs.frappe.io/erpnext/accounting-introduction'),('Chart of accounts','https://docs.frappe.io/erpnext/chart-of-accounts'),('Sales invoice','https://docs.frappe.io/erpnext/sales-invoice'),('Purchase invoice','https://docs.frappe.io/erpnext/purchase-invoice'),('Payment entry','https://docs.frappe.io/erpnext/payment-entry'),('Journal entry','https://docs.frappe.io/erpnext/journal-entry'),('Bank reconciliation','https://docs.frappe.io/erpnext/bank-reconciliation'),('Accounting dimensions','https://docs.frappe.io/erpnext/accounting-dimensions'),('Budgets','https://docs.frappe.io/erpnext/budget'),('Accounting reports','https://docs.frappe.io/erpnext/accounting-reports'),('Role-based permissions','https://docs.frappe.io/erpnext/role-based-permissions'),('Immutable ledger','https://docs.frappe.io/erpnext/immutable-ledger-in-erpnext'),('Accounting entries','https://docs.frappe.io/erpnext/accounting-entries'),('Inventory accounting','https://docs.frappe.io/erpnext/accounting-of-inventory-stock'),('Finance books','https://docs.frappe.io/erpnext/finance-book'),('Frappe Books product overview','https://frappe.io/books'),('Frappe Books reports','https://docs.frappe.io/books/reports'),('General ledger','https://docs.frappe.io/erpnext/general-ledger')]
exec(helpers)
feature=tree('ERPNext Accounting feature tree','ERPNEXT|Accounting',[
('Foundation',['Company, fiscal year and currency','Chart of accounts and opening balances','Customers, suppliers and bank accounts']),('Sales & collection',['Sales invoices and customer balances','Payment terms and payment allocations','Returns, credits and receivables review']),('Purchases & costs',['Purchase invoices and supplier balances','Supplier payments and advances','Expense / asset / inventory accounting']),('Bank & cash',['Receive, Pay and Internal Transfer','Statement matching and clearance','Unallocated payment reconciliation']),('Ledger & control',['Journal entries and general ledger','Cancellation reversals and traceability','Roles, permissions and period controls']),('Management view',['Cost centers, projects and dimensions','Budgets and variance review','Alternate reporting with finance books']),('Reports & links',['Trial balance, balance sheet and P&L','Cash flow, receivables and payables','Linked stock, asset and other workflows'])])
workflow=tree('ERPNext Accounting workflow tree','COMPANY|Accounting cycle',[
('1. Set up',['Company, dates and account structure','Parties, currency, taxes and defaults','Opening figures checked by accountant']),('2. Prepare',['Sales Invoice for customer billing','Purchase Invoice for supplier billing','Journal Entry for deliberate adjustments']),('3. Submit',['Validate document and account mapping','Submission creates ledger postings','Drafts do not equal posted transactions']),('4. Settle',['Receive customer payment / pay supplier','Allocate full or partial invoice amounts','Track advances and outstanding balances']),('5. Reconcile',['Match payments to invoices as required','Match bank statement to recorded vouchers','Resolve fees, differences and duplicates']),('6. Analyse',['Review general ledger and trial balance','Check profit, position and cash flow','Filter by cost center, project or dimension']),('7. Control',['Use reversals and supported corrections','Review permissions and reporting periods','Retain evidence and test backup recovery'])])
(out/'feature-tree.svg').write_text(feature,encoding='utf-8');(out/'accounting-workflow-tree.svg').write_text(workflow,encoding='utf-8')
pages=[]
def page(title,body,kicker='PRODUCT & ACCOUNTING WORKFLOW GUIDE'):pages.append(dict(title=title,body=body,kicker=kicker))
page('Frappe Accounting','<div class="cover-title">ERPNext Accounting<br>features &amp; workflow</div><p class="lead">A practical reference for business teams: documents, money movements, ledger entries, financial reports and controls.</p><div class="cover-tags">FEATURE TREE / WORKFLOW TREE / WORKED EXAMPLE</div><div class="cover-bottom"><strong>Prepared for Judibas product discussion</strong><p>Research checked: 21 October 2026<br>Includes a separate Frappe Books overview</p></div>'+box('Independent guide based on official public documentation. No private ERPNext or Frappe Books account was inspected. Product behaviour depends on the installed version, permissions and configuration.'),'BUSINESS SOFTWARE REFERENCE')
page('01 / Scope and product names','<p><strong>ERPNext Accounting</strong> is the main subject of this guide. It connects financial records to business documents and their ledger effects. <strong>Frappe Books</strong> is a separate accounting product; it is summarized on page 16. Do not assume the two products share every screen or feature. [1, 16]</p>'+table(['Pages','What you will find'],[['3-4','Feature tree and accounting workflow tree'],['5-8','Setup, sales, purchases, payments and banking'],['9-12','Journals, budgets, reports, permissions and audit'],['13','Complete service-business accounting example'],['14-15','Related workflows, rollout checklist and glossary'],['16-17','Frappe Books overview and official sources']])+'<h3>The basic idea</h3><p>An operational document describes the business event. Submitting an accounting document creates its ledger effect. Receiving or paying money is a separate event from issuing an invoice. Reports summarize the resulting records. [1, 13]</p>'+box('<strong>Labels:</strong> [D] documented ERPNext behaviour. [C] dependent on setup, related modules or version. [E] illustrative example or recommended practice. This is an overview for understanding and scoping, not an exhaustive field-by-field implementation manual.')+refs([1,13,16]))
page('02 / Accounting feature tree','<p class="caption">Conceptual map of ERPNext Accounting. These branches explain the product structure rather than reproduce one version\'s navigation menu.</p><figure>'+feature+'</figure><p class="caption">Sources [1-12, 14-15, 18]. Operational integrations need their related modules and configuration.</p>')
page('03 / Accounting workflow tree','<p class="caption">How a business event becomes a posted accounting record, is settled, and appears in management reports.</p><figure>'+workflow+'</figure><p class="caption">Document and ledger flow: [3-7, 12-13]. Review and recovery activities in step 7 include recommended operating practices [E].</p>')
page('04 / Company and account setup','<h3>Chart of accounts [D]</h3><p>The chart is a hierarchy for assets, liabilities, equity, income and expenses. Group accounts organize the tree; actual postings use ledger accounts. Account type, company and currency influence how accounts can be used. [2]</p>'+table(['Account family','Plain-language purpose','Example [E]'],[['Assets','Resources controlled by the business','Bank, cash, receivables'],['Liabilities','Amounts owed','Supplier payables, accrued costs'],['Equity','Owner interest and retained results','Capital, retained earnings'],['Income','Revenue earned','Consulting revenue'],['Expenses','Costs incurred','Rent, utilities']])+'<h3>Recommended setup order [E]</h3>'+bullets(['Confirm company identity, reporting currency and fiscal dates.','Agree the account structure and default receivable/payable accounts.','Prepare customer, supplier, item and bank details.','Configure relevant taxes, payment terms and cost centers.','Choose one migration cutoff and reconcile opening balances.','Test draft and submitted transactions before wider rollout.'])+box('Company setup defines the accounting entity. A department or project reporting tag does not create another legal company. Avoid building a separate account for every department when a dimension can represent that distinction. [8]')+refs([2,8]))
page('05 / Sales and customer collection','<h3>Sales Invoice [D]</h3><p>A Sales Invoice records the customer obligation, income and applicable taxes when submitted. It can follow a Sales Order or Delivery Note, or be entered directly. Item income accounts, payment terms and reporting dimensions must be correct. Stock updating is a separate choice that must match the delivery workflow. [3]</p>'+table(['Step','Business purpose','Check [E]'],[['Prepare invoice','Define customer, goods/services and amount','Company, currency, dates and item rates'],['Review and submit','Post the invoice accounting effect','Income account, tax and due date'],['Record receipt','Recognize money received','Bank/cash account and reference'],['Allocate payment','Connect receipt to invoice','Correct invoice and allocation amount'],['Follow up','Collect the remaining balance','Receivables and overdue balances']])+'<h3>Partial payment example [E]</h3><p>Invoice the customer Rs 100,000 and receive Rs 60,000. If that receipt is allocated to the invoice, Rs 40,000 remains outstanding. The receipt is not a second sale. Multiple payments can settle one invoice, and a payment may cover several invoices. [5]</p>'+box('A draft invoice is not the same as a submitted invoice. A submitted invoice is not proof of payment. Keep document status, accounting posting and cash collection distinct.')+refs([3,5]))
page('06 / Purchases and supplier balances','<h3>Purchase Invoice [D]</h3><p>A Purchase Invoice records a supplier bill and, on submission, its payable and related expense, asset value or other account effects. It may be based on a Purchase Order or Purchase Receipt, or entered directly. Review supplier references and posting dates. [4]</p>'+table(['Scenario','Typical route','Key distinction'],[['Service bought on credit','Purchase Invoice, then Payment Entry','Expense and payment happen separately'],['Goods already received','Invoice from the existing Purchase Receipt','Avoid recording receipt twice'],['Goods and bill together','Invoice with stock update where appropriate','Requires the intended stock configuration'],['Supplier paid in advance','Advance Payment Entry and later allocation','Payment may precede the final invoice']])+'<h3>Unpaid supplier example [E]</h3><p>A service bill is Rs 30,000. After a payment of Rs 20,000 is allocated, Rs 10,000 remains payable. The bill still records a Rs 30,000 obligation; the payment settles part of it. [5]</p>'+box('<strong>Recommended check [E]:</strong> confirm whether stock was already received through another voucher before enabling invoice stock updates. Check duplicate supplier invoice references before submission.')+refs([4,5,14]))
page('07 / Payments, allocation and banking','<h3>Payment Entry [D]</h3><p>Payment Entry supports Receive, Pay and Internal Transfer. It records account movements, parties, references and allocations. Advances may remain unallocated until matched later. [5]</p>'+table(['Tool','Purpose','What it does not prove'],[['Payment Entry','Record money received, paid or transferred','An unallocated receipt does not settle a specific invoice'],['Payment Reconciliation','Allocate existing payments/credits to invoices','It does not compare your books with a bank statement'],['Bank Reconciliation','Match statement lines with recorded vouchers','An imported statement line is not automatically a new sale'],['Internal Transfer','Move money between company accounts','It is not additional business income']])+'<h3>Bank reconciliation [D]</h3><p>Select the company bank account and date range, import or synchronize transactions through supported methods, and match statement activity to existing vouchers. Check for an existing record before creating a missing one. Record fees and explain timing differences. Verify the ending balance against the statement. [7]</p>'+box('A cheque reference is a payment reference, not a complete cheque-management lifecycle. Issued, held, deposited, cleared, returned and replaced cheque states need a separately agreed workflow [E]. Bank-provider support must also be verified for the chosen country and installation [C].')+refs([5,7]))
page('08 / Journals and ledger protection','<h3>Journal Entry [D]</h3><p>A Journal Entry records balanced debits and credits directly. It is suitable for adjustments, accruals, opening balances, write-offs and revaluations. Normal customer receipts and supplier payments are generally clearer through Payment Entry because it handles party and invoice allocations explicitly. [6]</p>'+table(['Illustrative event [E]','Debit','Credit'],[['Recognize unpaid electricity Rs 8,000','Utilities expense 8,000','Accrued liability 8,000'],['Owner deposits Rs 50,000','Bank 50,000','Owner capital 50,000'],['Expense prepaid for future period','Prepaid expense','Bank']])+'<h3>Corrections and cancellation [D]</h3><p>ERPNext\'s immutable-ledger design preserves original postings and records reversals on cancellation. Corrections should follow the supported document process rather than manually overwriting ledger rows. Backdated accounting or stock changes can affect later values and require careful diagnosis. [12]</p>'+box('<strong>Recommended control [E]:</strong> restrict journal and cancellation permissions, require a clear explanation and retain supporting evidence. A balanced journal can still use the wrong accounts, party or reporting period.')+refs([6,12]))
page('09 / Dimensions, budgets and books','<h3>Accounting dimensions [D]</h3><p>An account describes what occurred; a dimension describes the business segment. ERPNext treats Cost Center and Project as dimensions and supports configurable additional dimensions, such as Department. Required dimensions affect submission and should be tested across invoices, payments and journals. [8]</p>'+table(['Example [E]','Account','Reporting tag'],[['Marketing campaign','Advertising expense','Department = Marketing'],['Client implementation','Service revenue','Project = Client Portal'],['Office rent','Rent expense','Cost Center = Head Office']])+'<h3>Budgets [D / C]</h3><p>Budgets compare planned account amounts against activity for a configured segment and period. Warning or blocking depends on the selected transaction stages and control settings. Matching company, dates, account and dimension values matters. [9]</p><h3>Finance Book [D / C]</h3><p>Finance Books support alternate accounting treatments or report views within the same company. Use one only when that requirement exists; it is not a replacement for separate companies or department tagging. Keep the selected book explicit when comparing results. [15]</p>'+box('Recommended design [E]: begin with a clean account tree and a small number of useful dimensions. Add complexity only where it answers a real reporting or control requirement.')+refs([8,9,15]))
page('10 / Reports and management decisions','<p>Accounting reports present posted transactions from different perspectives. Choose the report according to the question, then trace unusual figures to source vouchers. [10, 18]</p>'+table(['Report','Question answered'],[['General Ledger','Which debit/credit entries produced this balance?'],['Trial Balance','What are opening, movement and closing balances by account?'],['Balance Sheet','What does the company own and owe on a date?'],['Profit and Loss','What income and expenses produced the period result?'],['Cash Flow','Why did cash change across business activities?'],['Accounts Receivable','Which customer invoices remain unpaid or overdue?'],['Accounts Payable','Which supplier amounts remain due?'],['Payment Ledger','How do invoice/payment allocations explain outstanding balances?']])+'<h3>Reading sequence [E]</h3>'+bullets(['Start with the financial statement or outstanding-balance report.','Confirm company, date range, currency and any dimension or Finance Book filters.','Open detailed ledger activity for an unexpected account or party.','Open the original submitted voucher and review its allocations.'])+box('A trial balance that balances is not proof that every transaction is correct. An incorrect expense classification can leave debits and credits perfectly equal [E].')+refs([10,18]))
page('11 / Roles, approvals and audit','<h3>Permission model [D]</h3><p>Roles grant access to document types and actions such as reading, writing and submitting. Additional user restrictions and field permission levels can narrow access. A job title alone should not determine unrestricted financial access. [11]</p>'+table(['Suggested responsibility [E]','Typical access to consider'],[['Accounts operator','Prepare invoices and payments within assigned company scope'],['Accountant','Review postings, reconcile accounts and prepare adjustments'],['Accounts manager','Authorize sensitive accounting actions and oversight'],['Business manager','Read permitted reports and relevant business documents'],['System administrator','Maintain the application; grant financial powers explicitly'],['Employee / customer','Only the documents and portal workflows relevant to them']])+'<h3>Document controls [E]</h3>'+bullets(['Separate preparation, approval and payment responsibilities where practical.','Test read, submit, cancel, amend, export and cross-company access.','Require clear references and evidence for sensitive changes.','Use supported reversal/correction processes and review period boundaries.','Test backup restoration; an export alone is not a complete recovery plan.'])+box('The responsibility matrix is a proposed operating policy. It is not a claim that these exact restrictions or approval stages are enabled by default. Configure and verify them in the chosen ERPNext version.')+refs([11,12]))
page('12 / Complete accounting example','<p class="caption">Original service-business illustration [E]: one currency, no tax, no stock, no opening balances and no other activity. Amounts are in rupees.</p>'+table(['Business event','Document','Illustrative posting'],[['Bill customer Rs 100,000','Submitted Sales Invoice','Debit receivables 100,000; credit revenue 100,000'],['Receive Rs 60,000','Allocated Receive Payment Entry','Debit bank 60,000; credit receivables 60,000'],['Supplier service bill Rs 30,000','Submitted Purchase Invoice','Debit expense 30,000; credit payables 30,000'],['Pay supplier Rs 20,000','Allocated Pay Payment Entry','Debit payables 20,000; credit bank 20,000']])+'<h3>What the reports should explain</h3>'+table(['Measure','Amount','Interpretation'],[['Revenue','Rs 100,000','Earned amount in this illustration'],['Expense','Rs 30,000','Cost incurred'],['Profit','Rs 70,000','Revenue minus expense'],['Net bank movement','Rs 40,000 increase','60,000 received minus 20,000 paid'],['Customer receivable','Rs 40,000','Still to collect'],['Supplier payable','Rs 10,000','Still to pay']])+box('Profit is not cash received. Payments change settlement and bank balances; they do not create another invoice. Exact account names and postings depend on configuration. This is an explanation of accounting logic, not a local tax calculation.')+refs([13,3,4,5]))
page('13 / Links with other business modules','<h3>Stock and inventory [D / C]</h3><p>Stock movements can connect to financial entries under perpetual inventory. Delivery, receipt and invoice flows must be designed together so that stock is not updated twice. Review stock account mappings and reconcile stock-related ledger values using the supported reports. [14]</p>'+table(['Related area','Relationship to accounting','Scope decision [E]'],[['Sales / CRM','A commercial opportunity can lead to an order and invoice','Decide the handover point from CRM'],['Purchasing / inventory','Receipts and supplier bills explain goods and obligations','Choose receipt versus invoice stock updating'],['Assets','Asset acquisition and subsequent accounting have specialized workflows','Confirm the asset module and policy'],['Projects','Project tags segment revenue and costs','Define shared project identifiers'],['HR / payroll','Payroll or claims can produce financial obligations','Confirm the installed HR/payroll apps'],['Cheque management','References and clearance relate to payments','Define the full cheque lifecycle separately']])+'<h3>For Judibas planning [E]</h3><p>Use this as a functional reference. A similar feature list does not migrate ERPNext\'s accounting engine into Laravel. Reusing ERPNext through integration versus implementing a Judibas-native ledger are different projects, with different data ownership, testing and maintenance requirements.</p>'+refs([1,8,14]))
page('14 / Rollout checklist and glossary','<h3>Recommended acceptance checks [E]</h3>'+bullets(['Opening balances and unpaid invoices match the agreed migration cutoff.','Invoice submission, partial payment and allocation produce expected balances.','Supplier bills, advances and final payments reconcile correctly.','Cancellation retains traceable original and reversal records.','Bank matching does not create duplicate transactions.','Reports agree under consistent company, period and dimension filters.','Unassigned users cannot read, modify or export another company\'s financial records.','Large exports, backups and simultaneous users are tested before launch.'])+'<h3>Plain-language glossary</h3>'+table(['Term','Meaning'],[['Ledger account','Posting account used to classify financial effects.'],['Voucher','Source accounting document linked to ledger activity.'],['Receivable / payable','Amount to collect / amount owed.'],['Allocation','Link between payment amount and an invoice or reference.'],['Cost center / dimension','Business segment used for analysis or control.'],['Journal','Deliberate balanced debit/credit entry.'],['Reversal','Opposite posting preserving the original transaction trail.'],['Reconciliation','Explaining differences between records and supporting evidence.']])+refs([2,5,6,7,12]))
page('15 / Frappe Books: separate product','<h3>Current product scope [D]</h3><p>The official Frappe Books site now describes a Frappe Framework application that teams can use in a browser on their own server, including from a phone. It states that the old desktop application is no longer supported. Older comparisons describing Books only as desktop software should therefore not be used for current product decisions. [16]</p><p>The product overview lists quotes, invoices, payments, supplier bills and returns; inventory and point of sale; double-entry accounting; and reports including Profit and Loss, Balance Sheet, General Ledger and Trial Balance. It also describes team permissions. [16]</p><h3>How to evaluate it separately [E]</h3>'+table(['Question','What to inspect'],[['Is the workflow simple enough for your team?','Try sales, purchasing and payment allocation with sample records.'],['Does it meet local requirements?','Verify relevant taxes, printed documents and any required local integrations.'],['Does it cover the controls you need?','Test permissions, corrections, reporting and recovery.'],['Does it fit the wider suite?','Compare actual integration needs against ERPNext and Judibas.']])+'<p>Its report documentation describes filtered report tables, exports and links back to underlying documents. Confirm the exact installed release before documenting a production workflow. [17]</p>'+box('The ERPNext feature and workflow trees in this guide describe ERPNext Accounting. They are not a promise that Frappe Books implements every ERPNext dimension, budget, permission or operational feature.')+refs([16,17]))
page('16 / Official sources','<p>Public official documentation checked on 21 October 2026. Menu labels, supported workflows and localization differ by release and configuration.</p><ol class="source-list">'+''.join('<li><strong>'+html.escape(title)+'</strong><br><a href="'+url+'">'+html.escape(url)+'</a></li>' for title,url in sources)+'</ol><p class="caption">This guide contains paraphrased research, original diagrams and illustrative examples. No private installation, production ledger or local regulatory integration was inspected.</p>')
css=next(ast.literal_eval(n.value) for n in ast.parse(old).body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='css' for t in n.targets))
css+='h1{font-size:24pt}.cover-title{font-size:31pt}.cover-bottom{margin-top:75px}.source-list{font-size:8.3pt}'
(out/'guide.css').write_text(css,encoding='utf-8')
html_doc='<!doctype html><html><head><meta charset="utf-8"><title>Frappe Accounting - ERPNext Guide</title><style>'+css+'</style></head><body>'+''.join('<section class="page"><div class="topline"></div><div class="kicker">'+p['kicker']+'</div><h1>'+p['title']+'</h1>'+p['body']+'<div class="footer"><span>JUDIBAS / FRAPPE ACCOUNTING REFERENCE</span><span>'+str(i+1)+' / '+str(len(pages))+'</span></div></section>' for i,p in enumerate(pages))+'</body></html>'
(out/'Frappe-Accounting-Guide.html').write_text(html_doc,encoding='utf-8');(out/'guide-content.json').write_text(json.dumps(pages,ensure_ascii=False),encoding='utf-8')
print('Created',len(pages),'guide pages')
